package com.example.domain.model.i18n

internal object DuaTe1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("నిద్ర నుండి మేల్కొన్నప్పుడు", "మరణం (నిద్ర) తర్వాత మనకు మళ్ళీ జీవం ఇచ్చిన అల్లాహ్‌కు సర్వ స్తుతి, ఆయన వైపుకే మన మరలింపు.", "నిద్ర నుండి మేల్కొన్న వెంటనే అల్లాహ్‌కు కృతజ్ఞత తెలుపడానికి.", "ప్రవక్త ﷺ మేల్కొన్న వెంటనే దీన్ని పఠించేవారు — కృతజ్ఞతతో, పరలోక స్మరణతో రోజు ప్రారంభం."),
        "dua_leaving_home" to DuaText("ఇంటి నుండి బయలుదేరేటప్పుడు", "అల్లాహ్ పేరుతో; నేను అల్లాహ్‌పై నమ్మకం ఉంచాను. అల్లాహ్ తప్ప శక్తి, బలం లేవు.", "ఇంటి నుండి బయటకు అడుగు పెట్టేటప్పుడు అల్లాహ్ రక్షణ కోరడానికి.", "దేవదూతలు చెబుతారు: నీకు మార్గదర్శనం, పోషణ, రక్షణ లభించింది, షైతాన్ దూరమవుతాడు."),
        "dua_anxiety_distress" to DuaText("దుఃఖం, ఆందోళన నుండి ఉపశమనం", "ఓ అల్లాహ్, దుఃఖం, ఆందోళన నుండి, బలహీనత, సోమరితనం నుండి, పిసినారితనం, పిరికితనం నుండి, అప్పుల భారం, ప్రజల ఆధిపత్యం నుండి నీ శరణు కోరుతున్నాను.", "దుఃఖం, ఆందోళన, అప్పుల భారం, మానసిక ఒత్తిడి సమయాల్లో.", "ప్రవక్త ﷺ దీన్ని తరచుగా పఠించేవారు — దుఃఖం, సోమరితనం, అప్పుల నుండి రక్షణ."),
        "dua_sayyidul_istighfar" to DuaText("సయ్యిదుల్ ఇస్తిగ్ఫార్", "ఓ అల్లాహ్, నీవే నా ప్రభువువు, నీవు తప్ప వేరే ఆరాధ్యుడు లేడు. నీవు నన్ను సృష్టించావు, నేను నీ దాసుడిని. నా శక్తి మేరకు నీ ఒప్పందం, వాగ్దానానికి కట్టుబడి ఉన్నాను. నా చేతల చెడు నుండి నీ శరణు కోరుతున్నాను. నాపై నీ అనుగ్రహాన్ని అంగీకరిస్తున్నాను, నా పాపాన్ని కూడా అంగీకరిస్తున్నాను, కాబట్టి నన్ను క్షమించు, నీవు తప్ప ఎవరూ పాపాలను క్షమించరు.", "ఉదయం, సాయంత్రం పఠించబడుతుంది — ప్రవక్త ﷺ నేర్పిన అత్యుత్తమ పశ్చాత్తాప ప్రార్థన.", "దృఢ విశ్వాసంతో సాయంత్రం పఠించి అదే రాత్రి మరణించినవాడు స్వర్గంలో ప్రవేశిస్తాడు; ఉదయం పఠించినా అదే ఫలితం."),
        "dua_parents" to DuaText("తల్లిదండ్రుల కోసం ప్రార్థన", "నా ప్రభువా, వారు నన్ను చిన్నతనంలో పెంచినట్లుగా వారిపై కరుణ చూపు.", "బాల్యంలో పెంపకానికి ప్రతిఫలంగా తల్లిదండ్రుల కోసం ఖురాన్ ప్రార్థన.", "తల్లిదండ్రుల కోసం ఈ ప్రార్థన చేయమని అల్లాహ్ స్వయంగా ఆదేశించాడు."),
        "dua_entering_mosque" to DuaText("మసీదులో ప్రవేశించేటప్పుడు", "ఓ అల్లాహ్, నీ కరుణా ద్వారాలను నాకు తెరువు.", "కుడి పాదంతో మసీదులో ప్రవేశించేటప్పుడు పఠించబడుతుంది.", "మసీదులో ప్రవేశించేటప్పుడు ప్రవక్త ﷺ ఈ ప్రార్థన నేర్పారు."),
        "dua_morning_asbahna" to DuaText("ఉదయపు స్మరణ", "మేము ఉదయాన్ని చేరుకున్నాము, ఈ ఉదయం మొత్తం అధికారం అల్లాహ్‌దే. సర్వ స్తుతి అల్లాహ్‌కే. అల్లాహ్ తప్ప ఆరాధ్యుడు లేడు, ఆయన ఏకైకుడు, భాగస్వాములు లేరు. అధికారం, స్తుతి ఆయనవే, ఆయన అన్నింటిపై శక్తిమంతుడు.", "ఉదయం పఠించే సున్నత్ ప్రార్థన.", "అల్లాహ్ అధికారాన్ని, ఏకత్వాన్ని అంగీకరిస్తూ రోజు ప్రారంభం."),
        "dua_evening_amsayna" to DuaText("సాయంత్రపు స్మరణ", "మేము సాయంత్రాన్ని చేరుకున్నాము, ఈ సాయంత్రం మొత్తం అధికారం అల్లాహ్‌దే. సర్వ స్తుతి అల్లాహ్‌కే. అల్లాహ్ తప్ప ఆరాధ్యుడు లేడు, ఆయన ఏకైకుడు, భాగస్వాములు లేరు. అధికారం, స్తుతి ఆయనవే, ఆయన అన్నింటిపై శక్తిమంతుడు.", "సాయంత్రం పఠించే సున్నత్ ప్రార్థన.", "అల్లాహ్ అధికారాన్ని, ఏకత్వాన్ని అంగీకరిస్తూ రాత్రి ప్రారంభం."),
        "dua_before_sleep" to DuaText("నిద్రించే ముందు", "ఓ అల్లాహ్, నీ పేరుతోనే నేను చనిపోతాను (నిద్రిస్తాను), బతుకుతాను (మేల్కొంటాను).", "మంచంపై పడుకున్న తర్వాత పఠించబడుతుంది.", "ప్రవక్త ﷺ నిద్రించే ముందు దీన్ని పఠించేవారు."),
        "dua_travel" to DuaText("ప్రయాణ ప్రార్థన", "దీన్ని మాకు వశపరచిన వానికి మహిమ కలుగుగాక, మేము దీన్ని స్వయంగా వశపరచుకోలేకపోయేవారం, నిశ్చయంగా మేము మా ప్రభువు వైపుకే మరలేవారం.", "వాహనంపై కూర్చున్న తర్వాత మూడుసార్లు అల్లాహు అక్బర్ అన్న తర్వాత పఠించబడుతుంది.", "రక్షణ, ఆశీర్వాదం కోసం ప్రయాణ సున్నత్ ప్రార్థన."),
        "dua_ayatul_kursi" to DuaText("నమాజ్ తర్వాత ఆయతుల్ కుర్సీ", "అల్లాహ్ — ఆయన తప్ప ఆరాధ్యుడు లేడు, శాశ్వతంగా జీవించేవాడు, అన్నింటినీ నిలిపేవాడు. నిద్ర, మగత ఆయనను తాకవు. ఆకాశాలలో, భూమిలో ఉన్నదంతా ఆయనదే. ఆయన అనుమతి లేకుండా ఆయన వద్ద సిఫారసు చేసేవారు ఎవరు? వారి ముందు, వెనుక ఉన్నదాన్ని ఆయన ఎరుగును. ఆయన జ్ఞానం నుండి ఆయన కోరినంత తప్ప వారు ఏమీ గ్రహించలేరు. ఆయన కుర్సీ ఆకాశాలను, భూమిని వ్యాపించి ఉంది, వాటి రక్షణ ఆయనకు అలసట కలిగించదు. ఆయన ఉన్నతుడు, మహనీయుడు.", "ప్రతి తప్పనిసరి నమాజ్ తర్వాత, నిద్రించే ముందు పఠించబడుతుంది.", "ప్రతి తప్పనిసరి నమాజ్ తర్వాత దీన్ని పఠించేవారికి స్వర్గంలో ప్రవేశించడానికి మరణం మాత్రమే అడ్డంకి; నిద్రించే ముందు పఠిస్తే ఉదయం వరకు రక్షణ."),
        "dua_hasbunallah" to DuaText("అల్లాహ్ మాకు చాలు", "అల్లాహ్ మాకు చాలు, ఆయన ఉత్తమ సంరక్షకుడు.", "శత్రు భయం లేదా పెద్ద ప్రమాదం సమయంలో.", "ఇబ్రాహీం ప్రవక్త (అ) అగ్నిలో వేయబడినప్పుడు ఇలా అన్నారు, ప్రవక్త ﷺ ప్రమాద సమయంలో కూడా అన్నారు."),
        "dua_entering_home" to DuaText("ఇంట్లో ప్రవేశించేటప్పుడు", "అల్లాహ్ పేరుతో (మేము ప్రవేశిస్తున్నాము).", "ఇంట్లో ప్రవేశించేటప్పుడు అల్లాహ్ పేరు చెప్పి సలాం చేయడం జరుగుతుంది.", "ఇంట్లో ప్రవేశించేటప్పుడు, భోజన సమయంలో అల్లాహ్‌ను స్మరిస్తే షైతాన్ అంటాడు: మీకు ఇక్కడ రాత్రి గడపడానికి, భోజనానికి స్థలం లేదు."),
        "dua_yunus" to DuaText("యూనుస్ ప్రవక్త (అ) ప్రార్థన", "నీవు తప్ప ఆరాధ్యుడు లేడు, నీవు పరిశుద్ధుడవు; నిశ్చయంగా నేను దుర్మార్గులలో ఒకడిని.", "చేప కడుపులో యూనుస్ ప్రవక్త (అ) ప్రార్థన — ప్రతి కష్టానికి.", "ఏ విషయంలోనైనా దీన్ని ప్రార్థించే ముస్లింకు అల్లాహ్ సమాధానం ఇస్తాడు."),
        "dua_karb" to DuaText("తీవ్ర కష్ట సమయపు ప్రార్థన", "మహోన్నతుడు, సహనశీలుడు అయిన అల్లాహ్ తప్ప ఆరాధ్యుడు లేడు. మహా సింహాసనానికి ప్రభువైన అల్లాహ్ తప్ప ఆరాధ్యుడు లేడు. ఆకాశాల, భూమి, గౌరవప్రద సింహాసనానికి ప్రభువైన అల్లాహ్ తప్ప ఆరాధ్యుడు లేడు.", "తీవ్ర కష్ట, బాధా సమయంలో పఠించబడుతుంది.", "ప్రవక్త ﷺ కష్ట సమయంలో దీన్ని పఠించేవారు."),
    )
}
